class ItemKind(OpenEnum):
    """The 19 core item kinds, plus extension kinds named `x:<namespace>.<name>`. `tool_call` is the generic fallback for tools that fit no other kind.
    
    Open: a value this client does not know is kept as a member that is not recognized."""
    USER_MESSAGE = "user_message"
    ASSISTANT_MESSAGE = "assistant_message"
    REASONING = "reasoning"
    COMMAND_EXECUTION = "command_execution"
    FILE_CHANGE = "file_change"
    FILE_READ = "file_read"
    FILE_SEARCH = "file_search"
    WEB_SEARCH = "web_search"
    MCP_TOOL_CALL = "mcp_tool_call"
    DYNAMIC_TOOL_CALL = "dynamic_tool_call"
    TOOL_CALL = "tool_call"
    TODO_LIST = "todo_list"
    PROPOSED_PLAN = "proposed_plan"
    COMPACTION = "compaction"
    REVIEW = "review"
    IMAGE = "image"
    SUBAGENT_SPAWN = "subagent_spawn"
    SYSTEM_NOTICE = "system_notice"
    ERROR = "error"


class ItemStatus(OpenEnum):
    """`completed`, `failed`, `cancelled` and `interrupted` are terminal: an item settles when it first reaches one of them.
    
    Open: a value this client does not know is kept as a member that is not recognized."""
    PENDING = "pending"
    RUNNING = "running"
    WAITING = "waiting"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"
    INTERRUPTED = "interrupted"


class FileChangeKind(OpenEnum):
    """Open: a value this client does not know is kept as a member that is not recognized."""
    ADD = "add"
