@dataclass(kw_only=True)
class Item:
    """One item of turn output. Payload fields by kind: messages and reviews use `text` (user messages may add `content`); `reasoning` uses `reasoning`; `command_execution` uses `command`, `cwd`, `exitCode`, `durationMs` and `output`; `file_change` uses `changes`; `file_read` uses `paths` and `output`; `file_search` and `web_search` use `query` and `results`; tool kinds use `tool` and `output`; `todo_list` uses `todos`; `proposed_plan` uses `plan`; `compaction` uses `text` for the summary; `image` uses `image`; `subagent_spawn` uses `subagentId`; `system_notice` uses `text`; `error` uses `error`; extension kinds use `data` and `fallback`."""
    id: str
    kind: ItemKind
    native: NativeRef
    status: ItemStatus
    turn_id: str | None = None
    parent_item_id: str | None = None
    title: str | None = None
    started_at: str | None = None
    completed_at: str | None = None
    truncated: bool | None = None
    """True when tool output or a diff hit the session's payload limits."""
    host_meta: AnyValue | Unset = UNSET
    """Host metadata echoed back on user messages."""
    text: str | None = None
    content: list[ContentBlock] | None = None
    reasoning: str | None = None
    output: str | None = None
    plan: str | None = None
    command: list[str] | None = None
    cwd: str | None = None
    exit_code: int | None = None
    duration_ms: float | None = None
    changes: list[FileChange] | None = None
    paths: list[str] | None = None
    query: str | None = None
    results: list[SearchResult] | None = None
    tool: ToolInvocation | None = None
    todos: list[TodoEntry] | None = None
    image: ImageContent | None = None
    subagent_id: str | None = None
    request_id: str | None = None
    """The request this item waits on, if any."""
    error: ItemError | None = None
    data: AnyValue | Unset = UNSET
    fallback: Fallback | None = None

    @classmethod
    def from_json(cls, data: Any) -> Item:
        data = require_object(data, "Item")
        return cls(
            id=required(data, "id", decode_str),
            kind=required(data, "kind", ItemKind.from_json),
            native=required(data, "native", NativeRef.from_json),
            status=required(data, "status", ItemStatus.from_json),
            turn_id=optional(data, "turnId", decode_str),
            parent_item_id=optional(data, "parentItemId", decode_str),
            title=optional(data, "title", decode_str),
            started_at=optional(data, "startedAt", decode_str),
            completed_at=optional(data, "completedAt", decode_str),
            truncated=optional(data, "truncated", decode_bool),
            host_meta=present(data, "hostMeta", decode_any_value),
            text=optional(data, "text", decode_str),
            content=optional(data, "content", list_of(decode_content_block)),
            reasoning=optional(data, "reasoning", decode_str),
            output=optional(data, "output", decode_str),
            plan=optional(data, "plan", decode_str),
            command=optional(data, "command", list_of(decode_str)),
            cwd=optional(data, "cwd", decode_str),
            exit_code=optional(data, "exitCode", decode_int),
            duration_ms=optional(data, "durationMs", decode_float),
            changes=optional(data, "changes", list_of(FileChange.from_json)),
            paths=optional(data, "paths", list_of(decode_str)),
            query=optional(data, "query", decode_str),
            results=optional(data, "results", list_of(SearchResult.from_json)),
            tool=optional(data, "tool", ToolInvocation.from_json),
            todos=optional(data, "todos", list_of(TodoEntry.from_json)),
            image=optional(data, "image", ImageContent.from_json),
            subagent_id=optional(data, "subagentId", decode_str),
            request_id=optional(data, "requestId", decode_str),
            error=optional(data, "error", ItemError.from_json),
            data=present(data, "data", decode_any_value),
            fallback=optional(data, "fallback", Fallback.from_json),
        )

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["id"] = encode(self.id)
        out["kind"] = encode(self.kind)
        out["native"] = encode(self.native)
        out["status"] = encode(self.status)
        if self.turn_id is not None:
            out["turnId"] = encode(self.turn_id)
        if self.parent_item_id is not None:
            out["parentItemId"] = encode(self.parent_item_id)
        if self.title is not None:
            out["title"] = encode(self.title)
        if self.started_at is not None:
            out["startedAt"] = encode(self.started_at)
        if self.completed_at is not None:
            out["completedAt"] = encode(self.completed_at)
        if self.truncated is not None:
            out["truncated"] = encode(self.truncated)
        if not isinstance(self.host_meta, Unset):
            out["hostMeta"] = encode(self.host_meta)
        if self.text is not None:
            out["text"] = encode(self.text)
        if self.content is not None:
            out["content"] = encode(self.content)
        if self.reasoning is not None:
            out["reasoning"] = encode(self.reasoning)
        if self.output is not None:
            out["output"] = encode(self.output)
        if self.plan is not None:
            out["plan"] = encode(self.plan)
        if self.command is not None:
            out["command"] = encode(self.command)
        if self.cwd is not None:
            out["cwd"] = encode(self.cwd)
        if self.exit_code is not None:
            out["exitCode"] = encode(self.exit_code)
        if self.duration_ms is not None:
            out["durationMs"] = encode(self.duration_ms)
        if self.changes is not None:
            out["changes"] = encode(self.changes)
        if self.paths is not None:
            out["paths"] = encode(self.paths)
        if self.query is not None:
            out["query"] = encode(self.query)
        if self.results is not None:
            out["results"] = encode(self.results)
        if self.tool is not None:
            out["tool"] = encode(self.tool)
        if self.todos is not None:
            out["todos"] = encode(self.todos)
        if self.image is not None:
            out["image"] = encode(self.image)
        if self.subagent_id is not None:
            out["subagentId"] = encode(self.subagent_id)
        if self.request_id is not None:
            out["requestId"] = encode(self.request_id)
        if self.error is not None:
            out["error"] = encode(self.error)
        if not isinstance(self.data, Unset):
            out["data"] = encode(self.data)
        if self.fallback is not None:
            out["fallback"] = encode(self.fallback)
        return out


